// Runs when any LendLoop workflow fails (set as their Error Workflow), so failed
// runs are visible instead of silent. Swap the log for Slack/email in production.
const e = $json;
const failure = {
  workflow: e.workflow?.name,
  executionId: e.execution?.id,
  failedNode: e.execution?.lastNodeExecuted,
  error: e.execution?.error?.message,
  url: e.execution?.url,
  at: new Date().toISOString(),
};
console.error('[LendLoop automation failure]', JSON.stringify(failure));
return [{ json: failure }];
